declare(strict_types=1);

/**
 * Settings. Defaults come from config.example.php; your local config.php overrides them.
 * An unknown key is a bug (usually a typo), so it throws instead of returning null.
 */
final class Config
{
    private static ?array $values = null;

    /** Pass a second argument to get a fallback instead of an exception for an unlisted key. */
    public static function get(string $key, $default = null)
    {
        $values = self::load();
        if (array_key_exists($key, $values)) {
            return $values[$key];
        }
        if (func_num_args() > 1) {
            return $default;
        }
        throw new LogicException("Unknown config key '$key'. Add it to config.example.php.");
    }

    /** Absolute path of the project root (the folder that holds api/, classes/, public/). */
    public static function root(): string
    {
        return dirname(__DIR__);
    }

    /** For tests only: replace some settings for the rest of the run. */
    public static function override(array $values): void
    {
        self::load();
        self::$values = array_replace(self::$values, $values);
    }

    private static function load(): array
    {
        if (self::$values !== null) {
            return self::$values;
        }
        $root = self::root();
        $defaults = require $root . '/config.example.php';
        $local = is_file($root . '/config.php') ? require $root . '/config.php' : [];
        if (!is_array($defaults) || !is_array($local)) {
            throw new LogicException('config.example.php and config.php must each return an array.');
        }
        return self::$values = array_replace($defaults, $local);
    }
}

/**
 * One PDO connection per request. Prepared statements only.
 *
 * - Parameters can be positional (?) or named (:name). With real prepared statements a
 *   named placeholder cannot be used twice in one query; use two names instead.
 * - Integers bind as integers, null as NULL, everything else as a string.
 * - DECIMAL columns come back as strings: cast them before putting them in JSON.
 * - The connection runs in UTC, so NOW() and every DATETIME column are UTC.
 * - execute() returns the number of rows MATCHED by the WHERE clause (not only changed).
 */
final class Database
{
    private static ?PDO $pdo = null;
    private static int $depth = 0;

    public static function pdo(): PDO
    {
        if (self::$pdo !== null) {
            return self::$pdo;
        }
        $dsn = sprintf(
            'mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',
            Config::get('db_host'),
            (int) Config::get('db_port'),
            Config::get('db_name')
        );
        try {
            $pdo = new PDO($dsn, (string) Config::get('db_user'), (string) Config::get('db_pass'), [
                PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                PDO::ATTR_EMULATE_PREPARES   => false,
                PDO::MYSQL_ATTR_FOUND_ROWS   => true,
            ]);
            $pdo->exec("SET time_zone = '+00:00'");
        } catch (PDOException $e) {
            // Never show connection details to the browser; the handler logs the cause.
            throw new ApiException('service_unavailable', 'The service is temporarily unavailable. Try again shortly.', 503, [], $e);
        }
        return self::$pdo = $pdo;
    }

    public static function fetchOne(string $sql, array $params = []): ?array
    {
        $row = self::run($sql, $params)->fetch();
        return $row === false ? null : $row;
    }

    public static function fetchAll(string $sql, array $params = []): array
    {
        return self::run($sql, $params)->fetchAll();
    }

    /** Runs INSERT/UPDATE/DELETE. Returns the number of matched rows. */
    public static function execute(string $sql, array $params = []): int
    {
        return self::run($sql, $params)->rowCount();
    }

    public static function lastInsertId(): int
    {
        return (int) self::pdo()->lastInsertId();
    }

    /**
     * Re-entrant: the outermost call opens the transaction and commits (or rolls back if
     * anything throws). A nested call just runs inside the open transaction, so the
     * exception must be allowed to propagate for the whole thing to roll back.
     */
    public static function transaction(callable $fn)
    {
        $pdo = self::pdo();
        if (self::$depth > 0) {
            self::$depth++;
            try {
                return $fn();
            } finally {
                self::$depth--;
            }
        }
        $pdo->beginTransaction();
        self::$depth = 1;
        try {
            $result = $fn();
            $pdo->commit();
            return $result;
        } catch (Throwable $e) {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
            throw $e;
        } finally {
            self::$depth = 0;
        }
    }

    private static function run(string $sql, array $params): PDOStatement
    {
        $stmt = self::pdo()->prepare($sql);
        foreach ($params as $key => $value) {
            $name = is_int($key) ? $key + 1 : (str_starts_with((string) $key, ':') ? (string) $key : ':' . $key);
            if (is_bool($value)) {
                $value = (int) $value;
            }
            $type = $value === null ? PDO::PARAM_NULL : (is_int($value) ? PDO::PARAM_INT : PDO::PARAM_STR);
            $stmt->bindValue($name, $value, $type);
        }
        $stmt->execute();
        return $stmt;
    }
}

/** Builds every JSON answer. All of them exit, so a route cannot send two responses. */
final class Response
{
    public static function success($data, int $status = 200): void
    {
        self::sendJson($status, ['data' => $data]);
    }

    /**
     * $fields is always sent as an object ({} when empty). A 429 with
     * $fields['retryAfterSeconds'] also gets the Retry-After header.
     */
    public static function error(string $code, string $message, int $status, array $fields = []): void
    {
        if ($status === 429 && isset($fields['retryAfterSeconds']) && !headers_sent()) {
            header('Retry-After: ' . (int) $fields['retryAfterSeconds']);
        }
        self::sendJson($status, ['error' => ['code' => $code, 'message' => $message, 'fields' => (object) $fields]]);
    }

    /** Streams PDF bytes as a download. Never reveals a file path. */
    public static function pdf(string $bytes, string $filename): void
    {
        self::discardOutput();
        $safe = preg_replace('/[^A-Za-z0-9._-]/', '_', $filename);
        http_response_code(200);
        header('Content-Type: application/pdf');
        header('Content-Disposition: attachment; filename="' . $safe . '"');
        header('Content-Length: ' . strlen($bytes));
        header('Cache-Control: no-store');
        header('X-Content-Type-Options: nosniff');
        echo $bytes;
        exit;
    }

    /** A database DATETIME (UTC) as an ISO 8601 string such as 2026-10-10T08:30:00Z. null stays null. */
    public static function iso(?string $dbDatetime): ?string
    {
        if ($dbDatetime === null || $dbDatetime === '') {
            return null;
        }
        $date = new DateTimeImmutable($dbDatetime, new DateTimeZone('UTC'));
        return $date->format('Y-m-d\TH:i:s\Z');
    }

    /** A DECIMAL naira amount (e.g. "5000.00") as the integer naira the API uses. */
    public static function naira($amount): int
    {
        return (int) round((float) $amount);
    }

    private static function sendJson(int $status, array $payload): void
    {
        self::discardOutput();
        http_response_code($status);
        header('Content-Type: application/json; charset=utf-8');
        header('Cache-Control: no-store');
        header('X-Content-Type-Options: nosniff');
        echo json_encode(
            $payload,
            JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE | JSON_THROW_ON_ERROR
        );
        exit;
    }

    /** Drops anything echoed earlier (stray whitespace, warnings) so it cannot corrupt the body. */
    private static function discardOutput(): void
    {
        while (ob_get_level() > 0) {
            ob_end_clean();
        }
    }
}

/** Reads the incoming request. Never trusts the browser for ids that belong to the session. */
final class Request
{
    private static ?array $json = null;

    public static function method(): string
    {
        return strtoupper($_SERVER['REQUEST_METHOD'] ?? 'GET');
    }

    /** A request header by its normal name, e.g. header('Idempotency-Key'). null when absent. */
    public static function header(string $name): ?string
    {
        $key = 'HTTP_' . strtoupper(str_replace('-', '_', $name));
        $value = $_SERVER[$key] ?? null;
        return is_string($value) && $value !== '' ? $value : null;
    }

    /** The caller's address. Only REMOTE_ADDR: forwarded headers can be forged. */
    public static function ip(): string
    {
        return (string) ($_SERVER['REMOTE_ADDR'] ?? '0.0.0.0');
    }

    public static function acceptsPdf(): bool
    {
        return stripos((string) Request::header('Accept'), 'application/pdf') !== false;
    }

    /** The JSON body as an array. An empty body is []. Anything else that is not a JSON object is a 422. */
    public static function json(): array
    {
        if (self::$json !== null) {
            return self::$json;
        }
        $raw = file_get_contents('php://input');
        if ($raw === false || trim($raw) === '') {
            return self::$json = [];
        }
        $data = json_decode($raw, true);
        if (!is_array($data) || ($data !== [] && array_is_list($data))) {
            throw new ApiException('validation_failed', 'The request body must be a JSON object.', 422);
        }
        return self::$json = $data;
    }

    /** One query-string value (trimmed), or null when it is missing or not a plain string. */
    public static function query(string $key)
    {
        $value = $_GET[$key] ?? null;
        return is_string($value) ? trim($value) : null;
    }

    /** Decodes the tr_ id from ?id=. Missing: 422. Malformed: 404, so ids cannot be probed. */
    public static function transcriptId(): int
    {
        $id = self::query('id');
        if ($id === null || $id === '') {
            throw new ApiException('validation_failed', 'Provide the transcript request id.', 422, ['id' => 'A transcript id is required.']);
        }
        return IdCodec::decode('tr', $id);
    }

    /**
     * Throws 422 validation_failed with a field message for each missing value.
     * $required is a list of names, or a map of name => message.
     */
    public static function requireFields(array $data, array $required): void
    {
        $fields = [];
        foreach ($required as $name => $message) {
            if (is_int($name)) {
                $name = (string) $message;
                $message = 'This field is required.';
            }
            $value = $data[$name] ?? null;
            if ($value === null || (is_string($value) && trim($value) === '')) {
                $fields[$name] = $message;
            }
        }
        if ($fields !== []) {
            throw new ApiException('validation_failed', 'Check the highlighted fields and try again.', 422, $fields);
        }
    }
}

/** A typed error. Throw it anywhere; the bootstrap turns it into the error envelope. */
final class ApiException extends Exception
{
    private string $errorCode;
    private int $httpStatus;
    private array $fields;

    public function __construct(string $code, string $message, int $status, array $fields = [], ?Throwable $previous = null)
    {
        parent::__construct($message, 0, $previous);
        $this->errorCode = $code;
        $this->httpStatus = $status;
        $this->fields = $fields;
    }

    public function errorCode(): string { return $this->errorCode; }
    public function httpStatus(): int { return $this->httpStatus; }
    public function fields(): array { return $this->fields; }
}

/**
 * Public ids the API shows: st_01, tr_1001, ad_01. The database keeps plain integers.
 * Any id that does not decode is a 404, never a hint about what exists.
 */
final class IdCodec
{
    /** prefix => [offset added to the database id, minimum digits]. */
    private const FORMATS = [
        'st' => [0, 2],
        'tr' => [1000, 4],
        'ad' => [0, 2],
    ];

    public static function encode(string $prefix, int $id): string
    {
        [$offset, $width] = self::format($prefix);
        return $prefix . '_' . str_pad((string) ($id + $offset), $width, '0', STR_PAD_LEFT);
    }

    public static function decode(string $prefix, string $publicId): int
    {
        [$offset] = self::format($prefix);
        $publicId = trim($publicId);
        if (preg_match('/^' . preg_quote($prefix, '/') . '_(\d{1,9})$/', $publicId, $m) === 1) {
            $id = (int) $m[1] - $offset;
            // Only the canonical spelling counts, so one record never has two public ids.
            if ($id >= 1 && self::encode($prefix, $id) === $publicId) {
                return $id;
            }
        }
        throw new ApiException('not_found', 'We could not find that record.', 404);
    }

    private static function format(string $prefix): array
    {
        return self::FORMATS[$prefix] ?? throw new LogicException("Unknown id prefix '$prefix'.");
    }
}

/**
 * Maps "METHOD path" to the closures returned by the three routes files.
 * api/.htaccess sends every api/**.php URL here, so contract URLs keep their .php ending.
 */
final class Router
{
    public static function dispatch(): void
    {
        $method = Request::method();
        $path = self::path();
        $routes = self::routes();

        if (isset($routes["$method $path"])) {
            $routes["$method $path"]();
            // Every route ends with Response::success/error/pdf, which exit.
            throw new LogicException("Route '$method $path' finished without sending a response.");
        }

        $allowed = [];
        foreach (array_keys($routes) as $key) {
            [$routeMethod, $routePath] = explode(' ', $key, 2);
            if ($routePath === $path) {
                $allowed[] = $routeMethod;
            }
        }
        if ($allowed !== []) {
            header('Allow: ' . implode(', ', $allowed));
            throw new ApiException('method_not_allowed', "This endpoint does not accept $method requests.", 405);
        }
        throw new ApiException('not_found', 'This endpoint does not exist.', 404);
    }

    /** "/portal/api/results/index.php?x=1" becomes "results/index". */
    private static function path(): string
    {
        $uri = rawurldecode((string) parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH));
        if (preg_match('#/api/(.*)$#', $uri, $m) !== 1) {
            return '';
        }
        $path = trim(preg_replace('#/+#', '/', $m[1]), '/');
        return (string) preg_replace('#\.php$#', '', $path);
    }

    private static function routes(): array
    {
        $routes = [];
        foreach (['routes_student.php', 'routes_account.php', 'routes_admin.php'] as $file) {
            $part = require Config::root() . '/api/' . $file;
            if (!is_array($part)) {
                throw new LogicException("$file must return an array of routes.");
            }
            foreach ($part as $key => $handler) {
                if (isset($routes[$key])) {
                    throw new LogicException("Route '$key' is defined in two routes files.");
                }
                $routes[$key] = $handler;
            }
        }
        return $routes;
    }
}
